(function(root){
 function composition(rows,profiles){const grouped=new Map(),known=new Map(profiles.map(p=>[p.key,p]));for(const r of rows){if(!Number.isSafeInteger(r.cents)||r.cents<0)throw Error('收入金额无效。');const key=known.get(r.member)?.active?r.member:'historical-other';grouped.set(key,(grouped.get(key)||0)+r.cents);}const total=[...grouped.values()].reduce((a,b)=>a+b,0);if(!Number.isSafeInteger(total))throw Error('收入合计超出计算范围。');return{total,parts:[...grouped].filter(([,cents])=>cents>0).map(([key,cents])=>({key,name:key==='historical-other'?'历史其他收入':known.get(key).name,cents,share:total?cents/total:0}))};}
 if(typeof module!=='undefined'&&module.exports){module.exports={composition};return;}
 const container=$('memberBars');container.classList.add('income-composition');const section=container.closest('article')||container.parentElement;section.querySelector('h2').textContent='家庭收入构成';const description=section.querySelector('.panel-head p');if(description)description.textContent='按所选期间的家庭已录收入计算占比；下方成员筛选只影响收入明细。';
 function color(key){const profiles=D.memberProfiles||[];return key==='historical-other'?'#8d929f':FamilyChartAxis.memberColor(profiles.find(p=>p.key===key),profiles.filter(p=>p.active).findIndex(p=>p.key===key));}
 function render(){if(!D.live)return;const r=D.report($('start').value,$('end').value,'全家'),data=composition(r.rows,D.memberProfiles||[]);container.replaceChildren();const date=document.createElement('p');date.className='muted full';date.textContent=r.start+' — '+r.end;container.append(date);if(!data.total){const p=document.createElement('p');p.className='empty';p.textContent='所选期间尚无已录收入，暂无收入占比。';container.append(p);return;}
  const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 260 260');svg.setAttribute('role','img');svg.setAttribute('aria-label','家庭收入构成，家庭合计'+money(data.total));svg.classList.add('income-donut');const tip=document.createElement('p');tip.className='composition-tip';tip.setAttribute('role','status');tip.textContent='点击或悬停扇区查看明细';let offset=0;
  for(const part of data.parts){const circle=document.createElementNS(svg.namespaceURI,'circle');circle.setAttribute('cx','130');circle.setAttribute('cy','130');circle.setAttribute('r','98');circle.setAttribute('fill','none');circle.setAttribute('stroke',color(part.key));circle.setAttribute('stroke-width','28');circle.setAttribute('pathLength','100');circle.setAttribute('stroke-dasharray',part.share*100+' '+(100-part.share*100));circle.setAttribute('stroke-dashoffset',String(-offset));circle.setAttribute('transform','rotate(-90 130 130)');circle.setAttribute('tabindex','0');const text=part.name+'：'+money(part.cents)+' · '+(part.share*100).toFixed(1)+'%';circle.setAttribute('aria-label',text);const title=document.createElementNS(svg.namespaceURI,'title');title.textContent=text;circle.append(title);circle.onpointerenter=circle.onfocus=circle.onclick=()=>tip.textContent=text;svg.append(circle);offset+=part.share*100;}
  for(const [y,text,size]of [[122,'家庭已录收入',12],[149,money(data.total),22]]){const t=document.createElementNS(svg.namespaceURI,'text');t.setAttribute('x','130');t.setAttribute('y',y);t.setAttribute('text-anchor','middle');t.setAttribute('font-size',size);t.setAttribute('fill','currentColor');t.textContent=text;svg.append(t);}const legend=document.createElement('div');legend.className='composition-legend';for(const part of data.parts){const b=document.createElement('button');b.type='button';b.className='composition-member';const dot=document.createElement('i');dot.style.background=color(part.key);const name=document.createElement('span'),value=document.createElement('strong');name.textContent=part.name;value.textContent=money(part.cents)+' · '+(part.share*100).toFixed(1)+'%';b.append(dot,name,value);b.onclick=()=>tip.textContent=part.name+'：'+money(part.cents)+' · '+(part.share*100).toFixed(1)+'%';legend.append(b);}container.append(svg,legend,tip);const note=document.createElement('p');note.className='muted full';note.textContent='占比反映已录收入构成，不代表资产占比；'+(data.parts.some(p=>p.key==='historical-other')?'“历史其他收入”包含已移除成员的历史收入。':'未知或未录收入不会被补成0。');container.append(note);
 }
 root.FamilyIncomeComposition={render};document.addEventListener('family-ledger-ready',render);document.addEventListener('family-app-ready',render);if(D.live)render();
})(typeof globalThis!=='undefined'?globalThis:this);
